function escAdmin(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));}let clientes=[];document.addEventListener('DOMContentLoaded',async()=>{try{clientes=await apiFetch('/operacoes/admin/clientes');render()}catch(e){document.getElementById('clientes-real').innerHTML='<tr><td colspan="4">'+escAdmin(e.message)+'</td></tr>'}});function render(){const q=(document.getElementById('busca').value||'').toLowerCase();const f=clientes.filter(c=>!q||[c.nome,c.email,c.telefone].some(x=>String(x||'').toLowerCase().includes(q)));document.getElementById('clientes-real').innerHTML=f.length?f.map(c=>'<tr><td>'+escAdmin(c.nome||'—')+'</td><td>'+escAdmin(c.email)+'</td><td>'+c.encomendas+'</td><td>'+Number(c.total_eur||0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'})+'</td></tr>').join(''):'<tr><td colspan="4">Nenhum cliente corresponde à pesquisa.</td></tr>'}document.getElementById('busca').oninput=render;
